entry.before:
-- 이 계좌 실험을 같은 잔액에서 재시험하는 공개 준비예요.
UPDATE account SET balance=100;
BEGIN;
UPDATE account SET balance=balance+10 WHERE id=1;
UPDATE account SET balance=balance+100 WHERE id=1;
ROLLBACK;

entry.after:
-- 이 계좌 실험을 같은 잔액에서 재시험하는 공개 준비예요.
UPDATE account SET balance=100;
BEGIN;
UPDATE account SET balance=balance+10 WHERE id=1;
SAVEPOINT bonus;
UPDATE account SET balance=balance+100 WHERE id=1;
ROLLBACK TO bonus;
COMMIT;
